struct sched_attr {
    __u32 size;
    __u32 sched_policy;
    __u64 sched_flags;
    // ... priority/nice fields
    __u64 sched_runtime;
    __u64 sched_deadline;
    __u64 sched_period;
};

struct sched_attr dl_attr = {
    .size = sizeof(dl_attr),
    .sched_policy = SCHED_DEADLINE,
    .sched_runtime = 10000000,
    .sched_deadline = 30000000,
    .sched_period = 50000000
};

// Apply SCHED_DEADLINE policy to the current thread (pid=0)
int ret = sched_setattr(0, &dl_attr, 0);
